import {locations,createWorld,advance,intervene} from './engine.js';
let world=createWorld(),selected=0,timer=null;const $=s=>document.querySelector(s);const time=t=>`${String(t%24).padStart(2,'0')}:00`;
function render(){ $('#day').textContent=`DAY ${String(Math.floor(world.tick/24)+1).padStart(2,'0')}`;$('#hour').textContent=time(world.tick);$('#weather').textContent=world.event;$('#places').innerHTML=locations.map((p,i)=>`<div class="place"><div class="place-label">0${i+1} / ${p.toUpperCase()}</div><div class="residents">${world.agents.map((a,j)=>a.place===i?`<button class="resident" data-agent="${j}" aria-pressed="${selected===j}">${a.name}</button>`:'').join('')}</div></div>`).join('');const a=world.agents[selected];$('#role').textContent=a.role;$('#inspector').innerHTML=`<div class="identity"><div class="avatar">${a.name[0]}</div><div><h3>${a.name}</h3><p>${locations[a.place]} · ${a.role}</p></div></div><p class="thought">“${a.thought}”</p>${[['energy','Energy'],['food','Fullness'],['social','Social connection']].map(([k,label])=>`<div class="need"><label for="${k}">${label}<span>${a[k]}%</span></label><progress id="${k}" value="${a[k]}" max="100"></progress></div>`).join('')}<p class="minor">RECENT MEMORIES</p><ul class="memory">${a.memories.length?a.memories.map(m=>`<li>${m}</li>`).join(''):'<li>No shared moments yet. Advance time to begin.</li>'}</ul><p class="minor">RELATIONSHIPS</p><p class="memory">${Object.entries(a.bonds).map(([n,v])=>`${n} · ${v} shared moments`).join('<br>')||'New faces, new possibilities.'}</p>`;$('#feed').innerHTML=world.log.map(e=>`<div class="entry"><time>D${Math.floor(e.tick/24)+1} ${time(e.tick)}</time><p>${e.text}</p></div>`).join('');}
function step(){advance(world);render();}function stop(){clearInterval(timer);timer=null;$('#run').textContent='▶ Run world';}$('#step').onclick=step;$('#run').onclick=()=>{if(timer)stop();else{timer=setInterval(step,2200);$('#run').textContent='Ⅱ Pause world';}};$('#reset').onclick=()=>{stop();world=createWorld();selected=0;render();};$('#places').onclick=e=>{const b=e.target.closest('[data-agent]');if(b){selected=Number(b.dataset.agent);render();}};document.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>{intervene(world,b.dataset.event);render();});render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{Promise.resolve(document.modelContext.registerTool({name:'advance_world',description:'Advance the NPC world by one simulated hour.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw new Error('Expected an empty object');step();return {tick:world.tick,agents:world.agents};}},{signal:lifecycle.signal})).catch(console.warn);}catch(e){console.warn(e);}}
